package com.yeyamo_mobile.api.booking_service.domain;import static org.junit.jupiter.api.Assertions.*;import java.math.BigDecimal;import java.time.*;import org.junit.jupiter.api.Test;import com.yeyamo_mobile.api.booking_service.infrastructure.persistence.*;
class BookingEntityTest{private ActivitySlotEntity slot(BigDecimal price){return ActivitySlotEntity.create("a","partner-1",Instant.now().plusSeconds(3600),Instant.now().plusSeconds(7200),5,price,"EUR");}@Test void paidBookingStartsPending(){var b=BookingEntity.pending("R","u",slot(BigDecimal.TEN),2);assertEquals(BookingStatus.PENDING,b.getStatus());assertEquals(PaymentStatus.AUTHORIZATION_PENDING,b.getPaymentStatus());assertEquals(new BigDecimal("20.00"),b.getTotalAmount());}@Test void authorizationConfirms(){var b=BookingEntity.pending("R","u",slot(BigDecimal.TEN),1);b.confirm();assertEquals(BookingStatus.CONFIRMED,b.getStatus());assertEquals(PaymentStatus.AUTHORIZED,b.getPaymentStatus());}@Test void paymentFailureCancels(){var b=BookingEntity.pending("R","u",slot(BigDecimal.TEN),1);b.paymentFailed("declined");assertEquals(BookingStatus.CANCELLED,b.getStatus());assertEquals(PaymentStatus.FAILED,b.getPaymentStatus());}@Test void paidCancellationRequestsRefund(){var b=BookingEntity.pending("R","u",slot(BigDecimal.TEN),1);b.confirm();b.cancel("user request");assertEquals(PaymentStatus.REFUND_PENDING,b.getPaymentStatus());}@Test void cannotCompletePendingBooking(){var b=BookingEntity.pending("R","u",slot(BigDecimal.TEN),1);assertThrows(BookingException.class,b::complete);}@Test void confirmedBookingCompletes(){var b=BookingEntity.pending("R","u",slot(BigDecimal.TEN),1);b.confirm();b.complete();assertEquals(BookingStatus.COMPLETED,b.getStatus());}@Test void freeBookingNeedsNoPayment(){assertEquals(PaymentStatus.NOT_REQUIRED,BookingEntity.pending("R","u",slot(BigDecimal.ZERO),1).getPaymentStatus());}}
